// Import legacy `.blacksite/*` artifacts into the relational store.
//
// Staged cutover (BLA-81 "Migration strategy"): we read the existing JSON/markdown
// primaries and project them into core_* tables. The parse functions are pure and
// produce deterministic IDs, so re-running the import is idempotent (INSERT OR IGNORE
// + stable ids) and never duplicates rows. The fs/apply layer is thin on top.

import * as fs from "fs";
import * as path from "path";
import type { DatabaseManager } from "./database-manager.js";
import type { VectorRecord } from "./vector-provider.js";

export interface ImportSource {
  id: string;
  kind: string;
  uri: string | null;
  title: string | null;
  metadata: Record<string, unknown> | null;
}

export interface ImportNote {
  id: string;
  kind: string;
  title: string | null;
  body: string;
  sourceId: string | null;
  createdAt: string | null;
  updatedAt: string | null;
}

export interface ImportRecords {
  sources: ImportSource[];
  notes: ImportNote[];
  embeddings: VectorRecord[];
}

export interface ImportSummary {
  sources: number;
  notes: number;
  embeddings: number;
}

const BLACKSITE_DIR = ".blacksite";

function stableId(prefix: string, ...parts: string[]): string {
  // FNV-1a over the joined parts → short, stable, collision-resistant enough for ids.
  let h = 0x811c9dc5;
  const input = parts.join("�");
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = (h * 0x01000193) >>> 0;
  }
  return `${prefix}_${h.toString(36)}`;
}

function emptyRecords(): ImportRecords {
  return { sources: [], notes: [], embeddings: [] };
}

function mergeRecords(target: ImportRecords, add: ImportRecords): void {
  target.sources.push(...add.sources);
  target.notes.push(...add.notes);
  target.embeddings.push(...add.embeddings);
}

// ── Pure parsers ─────────────────────────────────────────────────────────────

/** base-context.json → one source + one note per topic. */
export function parseBaseContext(json: unknown): ImportRecords {
  const records = emptyRecords();
  if (!json || typeof json !== "object") return records;
  const topics = (json as { topics?: unknown }).topics;
  if (!Array.isArray(topics)) return records;

  const sourceId = "src_base_context";
  records.sources.push({
    id: sourceId,
    kind: "base_context",
    uri: `${BLACKSITE_DIR}/base-context.json`,
    title: "Base Context",
    metadata: { topicCount: topics.length },
  });

  for (const topic of topics) {
    if (!topic || typeof topic !== "object") continue;
    const t = topic as Record<string, unknown>;
    const title = typeof t.title === "string" ? t.title : "Untitled topic";
    const notes = typeof t.notes === "string" ? t.notes : "";
    const id = typeof t.id === "string" && t.id ? stableId("note", "bc", t.id) : stableId("note", "bc", title);
    records.notes.push({
      id,
      kind: "base_context",
      title,
      body: notes || title,
      sourceId,
      createdAt: typeof t.createdAt === "string" ? t.createdAt : null,
      updatedAt: typeof t.updatedAt === "string" ? t.updatedAt : null,
    });
  }
  return records;
}

/** memory.md → one note per `## <timestamp>` section. */
export function parseMemoryMarkdown(markdown: string): ImportRecords {
  const records = emptyRecords();
  if (!markdown.trim()) return records;

  const sourceId = "src_memory_md";
  records.sources.push({
    id: sourceId,
    kind: "memory",
    uri: `${BLACKSITE_DIR}/memory.md`,
    title: "Project Memory",
    metadata: null,
  });

  // Sections delimited by level-2 headings; the first chunk before any heading is
  // the file's title block and is skipped.
  const sections = markdown.split(/^##\s+/m);
  for (let i = 1; i < sections.length; i++) {
    const section = sections[i]!;
    const newlineIdx = section.indexOf("\n");
    const heading = (newlineIdx >= 0 ? section.slice(0, newlineIdx) : section).trim();
    const body = (newlineIdx >= 0 ? section.slice(newlineIdx + 1) : "").trim();
    if (!body) continue;
    records.notes.push({
      id: stableId("note", "mem", heading, body.slice(0, 64)),
      kind: "memory",
      title: heading || null,
      body,
      sourceId,
      createdAt: heading || null,
      updatedAt: heading || null,
    });
  }
  return records;
}

/** memory-index.json (VectorStore format) → embedding records. */
export function parseMemoryIndex(json: unknown): ImportRecords {
  const records = emptyRecords();
  if (!json || typeof json !== "object") return records;
  const entries = (json as { entries?: unknown }).entries;
  if (!Array.isArray(entries)) return records;

  const sourceId = "src_memory_index";
  records.sources.push({
    id: sourceId,
    kind: "import",
    uri: `${BLACKSITE_DIR}/memory-index.json`,
    title: "Legacy Memory Index",
    metadata: { entries: entries.length },
  });

  for (const entry of entries) {
    if (!entry || typeof entry !== "object") continue;
    const e = entry as Record<string, unknown>;
    const vec = e.vec;
    if (!Array.isArray(vec) || vec.length === 0) continue;
    const id = typeof e.id === "string" && e.id ? e.id : stableId("emb", JSON.stringify(vec).slice(0, 64));
    const payload = (e.payload && typeof e.payload === "object" ? e.payload : {}) as Record<string, unknown>;
    const collection = typeof payload["_col"] === "string" ? (payload["_col"] as string) : "memory";
    records.embeddings.push({
      id,
      vector: vec.map((x) => Number(x)),
      payload,
      collection,
    });
  }
  return records;
}

/** planning.json → one note per plan (summary), preserving phase outline. */
export function parsePlanning(json: unknown): ImportRecords {
  const records = emptyRecords();
  if (!json || typeof json !== "object") return records;
  const plans = (json as { plans?: unknown }).plans;
  if (!Array.isArray(plans)) return records;

  const sourceId = "src_planning";
  records.sources.push({
    id: sourceId,
    kind: "plan",
    uri: `${BLACKSITE_DIR}/planning.json`,
    title: "Planning",
    metadata: { planCount: plans.length },
  });

  for (const plan of plans) {
    if (!plan || typeof plan !== "object") continue;
    const p = plan as Record<string, unknown>;
    const title = typeof p.title === "string" ? p.title : "Untitled plan";
    const summary = typeof p.summary === "string" ? p.summary : "";
    const phases = Array.isArray(p.phases) ? p.phases : [];
    const phaseLines = phases
      .map((phase) => (phase && typeof phase === "object" ? (phase as Record<string, unknown>).title : null))
      .filter((t): t is string => typeof t === "string")
      .map((t) => `- ${t}`)
      .join("\n");
    const body = [summary, phaseLines].filter(Boolean).join("\n\n") || title;
    const id = typeof p.id === "string" && p.id ? stableId("note", "plan", p.id) : stableId("note", "plan", title);
    records.notes.push({
      id,
      kind: "note",
      title: `Plan: ${title}`,
      body,
      sourceId,
      createdAt: typeof p.createdAt === "string" ? p.createdAt : null,
      updatedAt: typeof p.updatedAt === "string" ? p.updatedAt : null,
    });
  }
  return records;
}

// ── IO + apply ───────────────────────────────────────────────────────────────

function readJson(filePath: string): unknown {
  try {
    return JSON.parse(fs.readFileSync(filePath, "utf8")) as unknown;
  } catch {
    return null;
  }
}

function readText(filePath: string): string {
  try {
    return fs.readFileSync(filePath, "utf8");
  } catch {
    return "";
  }
}

/** Read every known legacy artifact under `<workspaceRoot>/.blacksite` and parse it. */
export function collectLegacyRecords(workspaceRoot: string): ImportRecords {
  const dir = path.join(workspaceRoot, BLACKSITE_DIR);
  const records = emptyRecords();
  mergeRecords(records, parseBaseContext(readJson(path.join(dir, "base-context.json"))));
  mergeRecords(records, parsePlanning(readJson(path.join(dir, "planning.json"))));
  mergeRecords(records, parseMemoryMarkdown(readText(path.join(dir, "memory.md"))));
  mergeRecords(records, parseMemoryIndex(readJson(path.join(dir, "memory-index.json"))));
  return records;
}

/** Persist parsed records idempotently. Existing rows (stable id) are left untouched. */
export async function applyImportRecords(db: DatabaseManager, records: ImportRecords): Promise<ImportSummary> {
  return db.enqueueWrite((driver) => {
    let sources = 0;
    let notes = 0;
    let embeddings = 0;
    driver.transaction(() => {
      for (const source of records.sources) {
        const result = driver.run(
          `INSERT OR IGNORE INTO core_sources (id, kind, uri, title, metadata)
           VALUES (:id, :kind, :uri, :title, :metadata)`,
          {
            id: source.id,
            kind: source.kind,
            uri: source.uri,
            title: source.title,
            metadata: source.metadata ? JSON.stringify(source.metadata) : null,
          },
        );
        sources += result.changes;
      }
      for (const note of records.notes) {
        const result = driver.run(
          `INSERT OR IGNORE INTO core_notes (id, kind, title, body, source_id, created_at, updated_at)
           VALUES (:id, :kind, :title, :body, :source_id, COALESCE(:created_at, datetime('now')), COALESCE(:updated_at, datetime('now')))`,
          {
            id: note.id,
            kind: note.kind,
            title: note.title,
            body: note.body,
            source_id: note.sourceId,
            created_at: note.createdAt,
            updated_at: note.updatedAt,
          },
        );
        notes += result.changes;
      }
      for (const emb of records.embeddings) {
        const norm = Math.sqrt(emb.vector.reduce((s, x) => s + x * x, 0)) || 1;
        const normalized = emb.vector.map((x) => x / norm);
        const result = driver.run(
          `INSERT OR IGNORE INTO core_embeddings (id, chunk_id, collection, model, dims, vector, norm, payload)
           VALUES (:id, NULL, :collection, :model, :dims, :vector, 1, :payload)`,
          {
            id: emb.id,
            collection: emb.collection ?? "memory",
            model: emb.model ?? null,
            dims: normalized.length,
            vector: JSON.stringify(normalized),
            payload: emb.payload ? JSON.stringify(emb.payload) : null,
          },
        );
        embeddings += result.changes;
      }
    });
    return { sources, notes, embeddings };
  });
}

/** True when the import has already populated core_meta with its completion marker. */
export function hasImported(db: DatabaseManager): boolean {
  const row = db.get<{ value: string }>("SELECT value FROM core_meta WHERE key = 'legacy_import_at'");
  return Boolean(row?.value);
}

export async function markImported(db: DatabaseManager, summary: ImportSummary): Promise<void> {
  await db.enqueueWrite((driver) => {
    driver.run(
      `INSERT INTO core_meta (key, value, updated_at) VALUES ('legacy_import_at', :value, datetime('now'))
       ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')`,
      { value: JSON.stringify({ at: new Date().toISOString(), ...summary }) },
    );
  });
}
